# ---- docstore.py: the wrapper ------------------------------------------------
from datetime import date, datetime
import httpx
from pydantic import BaseModel, field_validator
from tenacity import (retry, retry_if_exception, stop_after_attempt,
                      wait_exponential)

class DocumentNotFound(Exception): ...

class Document(BaseModel):
    id: str
    title: str
    created: date

    @field_validator("created", mode="before")
    @classmethod
    def parse_uk_date(cls, v):               # API sends "14/03/2026"
        return datetime.strptime(v, "%d/%m/%Y").date() if isinstance(v, str) else v

def make_client(base_url: str, token: str) -> httpx.Client:
    return httpx.Client(
        base_url=base_url,
        headers={"Authorization": f"Bearer {token}"},
        timeout=10,                                       # never wait forever
        transport=httpx.HTTPTransport(retries=3),         # retries failed connects only
    )

def _is_temporary(e: BaseException) -> bool:
    if isinstance(e, httpx.TransportError):               # timeout, dropped connection
        return True
    return (isinstance(e, httpx.HTTPStatusError)
            and e.response.status_code in (429, 500, 502, 503, 504))

@retry(retry=retry_if_exception(_is_temporary), stop=stop_after_attempt(4),
       wait=wait_exponential(multiplier=0.5, max=8), reraise=True)
def _get_page(client: httpx.Client, params: dict) -> dict:
    r = client.get("/documents", params=params)
    r.raise_for_status()               # 4xx/5xx become exceptions; only 429/5xx retry
    return r.json()

def list_documents(client: httpx.Client, claim_id: str) -> list[Document]:
    docs, cursor = [], None
    while True:
        params = {"claim_id": claim_id, **({"cursor": cursor} if cursor else {})}
        body = _get_page(client, params)
        if "error" in body:                  # API returns 200 with an error field
            raise DocumentNotFound(body["error"])
        docs += [Document.model_validate(d) for d in body["items"]]
        cursor = body.get("next_cursor")
        if not cursor:
            return docs

