import pytest

PAGE_1 = {"items": [{"id": "d1", "title": "Claim form", "created": "14/03/2026"}],
          "next_cursor": "abc"}                          # normally loaded from fixtures/
PAGE_2 = {"items": [{"id": "d2", "title": "Photo", "created": "15/03/2026"}],
          "next_cursor": None}
MISSING = {"error": "claim not found"}                   # the 200-with-error body

def fake_api(request: httpx.Request) -> httpx.Response:
    if request.url.params["claim_id"] == "DOES-NOT-EXIST":
        return httpx.Response(200, json=MISSING)
    if request.url.params.get("cursor") == "abc":
        return httpx.Response(200, json=PAGE_2)
    return httpx.Response(200, json=PAGE_1)

def test_follows_pagination_and_parses_dates():
    client = httpx.Client(base_url="https://test", transport=httpx.MockTransport(fake_api))
    docs = list_documents(client, "C-10442")
    assert [d.id for d in docs] == ["d1", "d2"]
    assert docs[0].created == date(2026, 3, 14)

def test_error_body_raises():
    client = httpx.Client(base_url="https://test", transport=httpx.MockTransport(fake_api))
    with pytest.raises(DocumentNotFound):
        list_documents(client, "DOES-NOT-EXIST")

def test_retries_a_503_then_succeeds():
    calls = []
    def flaky(request):
        calls.append(1)
        if len(calls) == 1:
            return httpx.Response(503)
        return httpx.Response(200, json=PAGE_2)
    client = httpx.Client(base_url="https://test", transport=httpx.MockTransport(flaky))
    assert len(list_documents(client, "C-1")) == 1 and len(calls) == 2

def test_401_is_not_retried():
    calls = []
    def denied(request):
        calls.append(1)
        return httpx.Response(401)
    client = httpx.Client(base_url="https://test", transport=httpx.MockTransport(denied))
    with pytest.raises(httpx.HTTPStatusError):
        list_documents(client, "C-1")
    assert len(calls) == 1

