import time
from collections import defaultdict

RETRYABLE = {429, 500, 502, 503, 504}          # temporary: worth another try

def fetch_all(client, max_attempts=4):
    """Yield orders from every page. Retry 429 and 5xx, fail fast on other errors."""
    page = 1
    while page:
        for attempt in range(max_attempts):
            status, body = client.get_orders(page)
            if status == 200:
                break                                # success: stop retrying
            if status not in RETRYABLE:              # 400, 401, 404: retrying won't help
                raise RuntimeError(f"page {page}: HTTP {status}")
            if attempt < max_attempts - 1:           # no pointless sleep after the last try
                time.sleep(2 ** attempt)             # back off: 1s, 2s, 4s
        else:
            raise RuntimeError(f"page {page}: still failing after {max_attempts} attempts")
        yield from body["orders"]
        page = body.get("next_page")

def revenue_by_customer(client):
    totals = defaultdict(float)
    for o in fetch_all(client):
        totals[o["customer_id"]] += o["amount"]
    return dict(totals)

