         2: {"orders": [{"customer_id": "a", "amount": 5.0}], "next_page": None}}

class FakeClient:
    """Returns the given statuses first, then real pages."""
    def __init__(self, first_statuses=()):
        self.queue, self.calls = list(first_statuses), 0
    def get_orders(self, page):
        self.calls += 1
        if self.queue:
            return self.queue.pop(0), {}
        return 200, PAGES[page]

@pytest.fixture(autouse=True)
def no_sleep(monkeypatch):
    monkeypatch.setattr(time, "sleep", lambda s: None)

def test_retries_429_and_500_then_pages():
    assert revenue_by_customer(FakeClient([429, 500])) == {"a": 15.0}

def test_404_fails_fast():
    client = FakeClient([404])
    with pytest.raises(RuntimeError, match="HTTP 404"):
        revenue_by_customer(client)
    assert client.calls == 1

def test_gives_up_after_max_attempts():
    client = FakeClient([503] * 4)
    with pytest.raises(RuntimeError, match="after 4 attempts"):
        revenue_by_customer(client)
    assert client.calls == 4

