from collections import deque
import heapq

callers = {                        # service -> services that call it
    "pricing": ["checkout", "quotes"],
    "checkout": ["web"], "quotes": ["web", "partner-api"],
    "web": [], "partner-api": [],
}

def bfs(start: str) -> dict[str, int]:
    dist = {start: 0}
    q = deque([start])
    while q:
        node = q.popleft()
        for nxt in callers[node]:
            if nxt not in dist:            # visited check
                dist[nxt] = dist[node] + 1
                q.append(nxt)
    return dist

