from collections import deque

def topo_order(deps: dict[str, list[str]]) -> list[str]:
    """Kahn's algorithm. deps maps task -> tasks it needs first."""
    needs = {t: len(pre) for t, pre in deps.items()}          # in-degree
    unlocks = {t: [] for t in deps}
    for t, pre in deps.items():
        for p in pre:
            unlocks[p].append(t)
    ready = deque(sorted(t for t, n in needs.items() if n == 0))
    order = []
    while ready:
        t = ready.popleft()
        order.append(t)
        for nxt in unlocks[t]:
            needs[nxt] -= 1
            if needs[nxt] == 0:                               # all prerequisites done
                ready.append(nxt)
    if len(order) < len(deps):                                # some tasks never ready
        stuck = sorted(t for t in deps if t not in order)
        raise ValueError(f"cycle among: {stuck}")
    return order

pipeline = {"extract": [], "clean": ["extract"], "embed": ["clean"],
            "index": ["embed"], "report": ["clean"]}
print(topo_order(pipeline))   # ['extract', 'clean', 'embed', 'report', 'index']
try:
    topo_order({"a": ["b"], "b": ["a"], "c": []})
except ValueError as e:
    print(e)                  # cycle among: ['a', 'b']

