from functools import cache

# 1. Recursion on tree-shaped data: total size of a nested folder (like nested JSON)
folder = {"name": "reports", "size": 2,
          "children": [{"name": "2025", "size": 40, "children": []},
                       {"name": "2026", "size": 5,
                        "children": [{"name": "q1", "size": 30, "children": []}]}]}

def total_size(node: dict) -> int:
    # base case is built in: a folder with no children just returns its own size
    return node["size"] + sum(total_size(c) for c in node["children"])

print(total_size(folder))          # 77

# 2. A binary search tree: smaller keys go left, larger go right
class Node:
    def __init__(self, key):
        self.key, self.left, self.right = key, None, None

def insert(root, key):
    if root is None:                         # base case: empty spot found
        return Node(key)
    if key < root.key:
        root.left = insert(root.left, key)
    else:
        root.right = insert(root.right, key)
    return root

def in_order(root):                          # left, node, right -> sorted order
    return [] if root is None else in_order(root.left) + [root.key] + in_order(root.right)

def height(root):
    return 0 if root is None else 1 + max(height(root.left), height(root.right))

root = None
for k in [50, 30, 70, 20, 40, 60]:
    root = insert(root, k)
print(in_order(root), height(root))  # [20, 30, 40, 50, 60, 70] 3

# 3. Memoization: the same sub-question asked again is answered from a cache
@cache
def ways_to_climb(n: int) -> int:        # 1 or 2 steps at a time
    if n <= 1:
        return 1                         # base case
    return ways_to_climb(n - 1) + ways_to_climb(n - 2)

print(ways_to_climb(40))                 # 165580141, instant with @cache

