import os, time
from collections import defaultdict, deque
from fastapi import FastAPI, HTTPException, Request
from pydantic import BaseModel, Field

app = FastAPI()
MOCK = os.getenv("MOCK_LLM") == "1" or not os.getenv("ANTHROPIC_API_KEY")
DAILY_LIMIT = int(os.getenv("DAILY_CALLS", "200"))   # budget guard: calls/day
PER_IP_PER_MIN = 5                                   # rate limit per visitor
calls_today = {"day": time.strftime("%Y-%m-%d"), "n": 0}
recent = defaultdict(deque)                          # ip -> call times

class Question(BaseModel):
    text: str = Field(min_length=1, max_length=500)  # short input = cheap calls

def allow(ip: str) -> None:
    now = time.time()
    q = recent[ip]
    while q and now - q[0] > 60:
        q.popleft()
    if len(q) >= PER_IP_PER_MIN:
        raise HTTPException(429, "Too many requests, try again in a minute")
    q.append(now)

def over_budget() -> bool:
    today = time.strftime("%Y-%m-%d")
    if calls_today["day"] != today:
        calls_today.update(day=today, n=0)
    return calls_today["n"] >= DAILY_LIMIT

def ask_llm(text: str) -> str:
    import anthropic                                  # key stays on the server
    resp = anthropic.Anthropic(timeout=15.0).messages.create(
        model="MODEL", max_tokens=300,
        messages=[{"role": "user", "content": text}])
    return "".join(b.text for b in resp.content if b.type == "text")

@app.post("/ask")
def ask(q: Question, request: Request):
    allow(request.client.host)
    if MOCK or over_budget():
        return {"answer": "[demo mode] A sample answer. Clone the repo to run it live.",
                "mode": "mock"}
    calls_today["n"] += 1
    return {"answer": ask_llm(q.text), "mode": "live"}


